const RC_USDT0: Json = {"status":"0x1","from":"0x58e7ca15b7ad6af451a455697f1f9acdba27cc98","to":"0x1231deb6f5749ef6ce6943a275a1d3e7486f4eae","logs":[{"address":"0x1231deb6f5749ef6ce6943a275a1d3e7486f4eae","topics":["0x7bfdfdb5e3a3776976e53cb0607060f54c5312701c8cba1155cc4d5394440b38"],"data":""},{"address":"0x1231deb6f5749ef6ce6943a275a1d3e7486f4eae","topics":["0xcba69f43792f9f399347222505213b55af8e0b0b54b893085c2e27ecbe1644f1"],"data":""}]};

// ---- stand-ins -----------------------------------------------------------------------------------------------------------------------

type Answer = { status?: number; body?: unknown; text?: string } | Error;
interface Asked {
  method: string;
  url: string;
  body: string | undefined;
}
/** LI.FI, as the test says it answers: the first rule whose pattern matches the URL answers; anything else is no network */
function lifi(rules: Array<[RegExp, Answer]>): Http & { asked: Asked[] } {
  const asked: Asked[] = [];
  const http = (async (url, init = {}) => {
    asked.push({ method: init.method ?? "GET", url, body: init.body });
    for (const [m, a] of rules) {
      if (!m.test(url)) continue;
      if (a instanceof Error) throw a;
      return { status: a.status ?? 200, body: a.body, text: a.text ?? JSON.stringify(a.body ?? "") };
    }
    return { status: 599, body: undefined, text: "no network in tests" };
  }) as Http & { asked: Asked[] };
  http.asked = asked;
  return http;
}
const both = (cheapest: Answer, fastest: Answer) => lifi([[/order=CHEAPEST/, cheapest], [/order=FASTEST/, fastest]]);
const NO_ROUTE: Answer = { status: 404, body: { message: "No available quotes for the requested transfer", code: 1002, errors: { filteredOut: [{ overallPath: "42161:USDC-across-8453:USDC-8453:USDC~8453:AERO", reason: "Bridge across requires a signature on the destination chain, but the request did not allow it (allowSwitchChain: false)" }], failed: [] } } };

/** a chain that holds what the test says: `"Arbitrum:USDC"` → whole tokens; `coin` the chain's own coin; read at every call */
interface Holds {
  held?: Record<string, number>;
  coin?: Partial<Record<ChainName, number>>;
  allowance?: bigint | undefined;
  decimals?: Record<string, number>;
  down?: ChainName[];
  receipts?: Record<string, Mined>;
  txs?: Record<string, SentTx>;
}
function chainStandIn(o: Holds = {}): ChainReader & { asked: string[] } {
  const asked: string[] = [];
  const down = (c: ChainName) => (o.down ?? []).includes(c);
  const decimals: Record<string, number> = { [USDC_ARB.toLowerCase()]: 6, [USDC_BASE.toLowerCase()]: 6, [USDT0_ARB.toLowerCase()]: 6, [USDC_ETH.toLowerCase()]: 6, [USDT_ETH.toLowerCase()]: 6, [USDC_BNB.toLowerCase()]: 18, ...o.decimals };
  return {
    asked,
    async tokens(holder, refs) {
      asked.push(`tokens:${holder}:${refs.map((r) => `${r.chain}:${r.asset}`).join(",")}`);
      const chains = [...new Set(refs.map((r) => r.chain))];
      return { rows: refs.filter((r) => !down(r.chain)).map((r) => ({ chain: r.chain, asset: r.asset, amount: o.held?.[`${r.chain}:${r.asset}`] ?? 0 })), failed: chains.filter(down) };
    },
    async native(holder, chains) {
      asked.push(`native:${holder}:${chains.join(",")}`);
      return { rows: chains.filter((c) => !down(c)).map((c) => ({ chain: c, asset: "ETH", amount: o.coin?.[c] ?? 0 })), failed: chains.filter(down) };
    },
    async uint(chain, address, signature, args = []) {
      asked.push(`uint:${chain}:${address}:${signature}:${args.join(",")}`);
      return o.allowance;
    },
    async decimals(chain, token) {
      asked.push(`decimals:${chain}:${token}`);
      return down(chain) ? undefined : decimals[token.toLowerCase()];
    },
    async receipt(chain, hash) {
      asked.push(`receipt:${chain}:${hash}`);
      return o.receipts?.[hash.toLowerCase()];
    },
    async transaction(chain, hash) {
      asked.push(`tx:${chain}:${hash}`);
      return o.txs?.[hash.toLowerCase()];
    },
  };
}
/** a wallet holding 500 USDC and 0.01 ETH on Arbitrum, that has allowed LI.FI's contract nothing yet */
const RICH: Holds = { held: { "Arbitrum:USDC": 500, "Arbitrum:USDT0": 500 }, coin: { Arbitrum: 0.01 }, allowance: 0n };

const routesFor = (http: Http, o: Partial<BridgeRouteRequest> = {}) => bridgeRoutes({ http, from: DEAD, to: DEAD, fromChain: "Arbitrum", toChain: "Base", asset: "USDC", toAsset: "USDC", amount: 100, chain: chainStandIn(RICH), now: () => T, ...o });

const refusal = (x: unknown): Refusal => {
  if (!isRefusal(x)) throw new Error(`expected a refusal, got ${JSON.stringify(x, (_k, v) => (typeof v === "bigint" ? v.toString() : v))}`);
  return x;
};
const ok = <T>(x: T | Refusal): T => {
  if (isRefusal(x)) throw new Error(`${x.code}: ${x.message}`);
  return x;
};
const lifiCalls = (h: { asked: Asked[] }) => h.asked.map((a) => `${a.method} ${a.url}`);

/** a quote whose calldata is taken apart, changed, and put back: what a forged, a careless or a stale answer would carry */
function recode(q: Json, change: (args: Json[]) => void): Json {
  const out = structuredClone(q);
  const d = decodeFunctionData({ abi: LIFI_BRIDGE_ABI, data: out.transactionRequest.data }) as unknown as { functionName: string; args: Json[] };
  const args = structuredClone([...d.args]);
  change(args);
  out.transactionRequest.data = encodeFunctionData({ abi: LIFI_BRIDGE_ABI, functionName: d.functionName, args } as never);
  return out;
}
/** an Across route that promises `units` (on chain and in LI.FI's summary). On `swapAndStart…` the contract throws `outputAmount` away
 * and asks the relayer for what is bridged (99.75 after LI.FI's fee) × `outputAmountMultiplier` / 1e18, so both are set, as LI.FI sets
 * them (the multiplier rounded up) */
const acrossPaying = (units: bigint) => {
  const bridged = 99_750_000n;
  const q = recode(Q_FASTEST, (a) => {
    a[2].outputAmount = units;
    a[2].outputAmountMultiplier = (units * 10n ** 18n + bridged - 1n) / bridged;
  });
  q.estimate.toAmount = q.estimate.toAmountMin = units.toString();
  return q;
};

// ---- the routes --------------------------------------------------------------------------------------------------------------------

describe("bridge routes: what is asked of LI.FI", () => {
  it("LI.FI's own calldata decodes with these ABIs and encodes back byte for byte (all four facets seen: Polymer CCTP, Across, Stargate)", () => {
    for (const q of [Q_CHEAPEST, Q_FASTEST, Q_STARGATE, Q_TOADDR]) {
      const call = decodeBridgeCall(q.transactionRequest.data);
      expect(call?.bridgeData.transactionId).toBe(q.transactionId);
      expect(recode(q, () => {}).transactionRequest.data).toBe(q.transactionRequest.data);
    }
    expect(decodeBridgeCall(Q_CHEAPEST.transactionRequest.data)!.facet).toBe("PolymerCCTP");
    expect(decodeBridgeCall(Q_STARGATE.transactionRequest.data)!.facet).toBe("Stargate");
    // the event LI.FI's contract logged in a real transfer
    expect(TRANSFER_STARTED_TOPIC).toBe("0xcba69f43792f9f399347222505213b55af8e0b0b54b893085c2e27ecbe1644f1");
    expect(BRIDGE_CHAINS).toEqual(["Ethereum", "Optimism", "BNB Chain", "Polygon", "Base", "Arbitrum"]);
  });

  it("two GETs, CHEAPEST and FASTEST, naming the destination, only the bridges that pay it themselves, and no call on arrival", async () => {
    const http = both({ body: Q_CHEAPEST }, { body: Q_FASTEST });
    ok(await routesFor(http));
    expect(lifiCalls(http).sort()).toEqual([`GET ${quoteUrl("CHEAPEST")}`, `GET ${quoteUrl("FASTEST")}`]);
    expect(http.asked.every((a) => a.body === undefined)).toBe(true);
  });

  it("an amount is in the token's own decimals, read from the token: 100 USDC on BNB Chain is 100 × 10^18 (and so without a chain reader)", async () => {
    for (const chain of [chainStandIn({ ...RICH, held: { "BNB Chain:USDC": 500 }, coin: { "BNB Chain": 1 } }), undefined]) {
      const http = both(NO_ROUTE, NO_ROUTE);
      refusal(await routesFor(http, { fromChain: "BNB Chain", toChain: "Arbitrum", toAsset: "USDT", chain }));
      expect(http.asked.map((a) => a.url)).toContain(quoteUrl("CHEAPEST", { fromChain: 56, toChain: 42161, fromToken: USDC_BNB, toToken: USDT0_ARB, amount: "100000000000000000000" }));
    }
  });

  it("refuses before asking anything: one chain, a chain without dollars, a coin that is not a dollar stablecoin there, a bad amount or address", async () => {
    const http = lifi([]);
    const cases: Array<[Partial<BridgeRouteRequest>, string]> = [
      [{ toChain: "Arbitrum" }, "E_ACCOUNT_BAD_ACTION"],
      [{ toChain: "Robinhood Chain" }, "E_ACCOUNT_BAD_ACTION"],
      [{ asset: "ETH" }, "E_ACCOUNT_UNPRICED"],
      [{ asset: "DAI" }, "E_ACCOUNT_UNPRICED"],
      [{ toAsset: "PYUSD" }, "E_ACCOUNT_UNPRICED"],
      [{ amount: 0 }, "E_ACCOUNT_BAD_ACTION"],
      [{ amount: 1.0000001 }, "E_ACCOUNT_BAD_ACTION"],
      [{ amount: Number.NaN }, "E_ACCOUNT_BAD_ACTION"],
      [{ to: "0x0000000000000000000000000000000000000000" }, "E_ACCOUNT_BAD_ACTION"],
      [{ to: "0x11f111f111f111F111f111f111F111f111f111F1" }, "E_ACCOUNT_BAD_ACTION"],
      [{ to: "nope" as Hex }, "E_ACCOUNT_BAD_ACTION"],
      [{ integrator: "a b" }, "E_ACCOUNT_BAD_ACTION"],
    ];
    for (const [o, code] of cases) expect(refusal(await routesFor(http, o)).code, JSON.stringify(o)).toBe(code);
    expect(http.asked).toEqual([]);
  });

  it("the wallet must hold what it sends: looked at before a quote is spent; a chain that does not answer spends none either", async () => {
    const http = both({ body: Q_CHEAPEST }, { body: Q_FASTEST });
    const poor = refusal(await routesFor(http, { chain: chainStandIn({ ...RICH, held: { "Arbitrum:USDC": 99.5 } }) }));
    expect(poor.code).toBe("E_VENUE_INSUFFICIENT");
    expect(poor.message).toContain("99.5 USDC on Arbitrum");
    expect(refusal(await routesFor(http, { chain: chainStandIn({ ...RICH, down: ["Arbitrum"] }) })).code).toBe("E_VENUE_UNREACHABLE");
    // a chain that answers without the token's row (its balance call reverted) has not said the wallet holds nothing
    const rowless = { ...chainStandIn(RICH), tokens: async () => ({ rows: [], failed: [] }) };
    expect(refusal(await routesFor(http, { chain: rowless })).code).toBe("E_VENUE_UNREACHABLE");
    expect(http.asked).toEqual([]);
  });
});

describe("bridge routes: two real choices, ranked", () => {
  it("CCTP (cheapest, ~18 min) before Across (seconds, 1.4¢ more): what arrives at worst, the fees, the gas, the time, the transaction", async () => {
    const chain = chainStandIn(RICH);
    const routes = ok(await routesFor(both({ body: Q_CHEAPEST }, { body: Q_FASTEST }), { chain }));
    expect(routes.map((r) => r.tool)).toEqual(["CCTP", "Across"]);
    const [cctp, across] = routes as [BridgeRoute, BridgeRoute];
    expect(cctp).toMatchObject({ id: Q_CHEAPEST.id, receiveUsd: 99.75, feeUsd: 0.25, gasUsd: 0.0137, etaSec: 1080 });
    expect(across).toMatchObject({ id: Q_FASTEST.id, receiveUsd: 99.736225, feeUsd: 0.263775, gasUsd: 0.0113, etaSec: 2 });
    expect(across.tx).toEqual({ chainId: 42161, chainIdHex: "0xa4b1", from: DEAD, to: LIFI_DIAMOND, data: Q_FASTEST.transactionRequest.data, value: "0x0", gas: "0x2ae58f" });
    expect(cctp.native).toMatchObject({ tool: "polymerStandard", orders: ["CHEAPEST"], usuallyWithinSec: 1512, transactionId: Q_CHEAPEST.transactionId, arrive: { least: "99.75", leastOnChain: "99.75" } });
    expect(across.native).toMatchObject({ tool: "across", orders: ["FASTEST"], usuallyWithinSec: 10, allowance: "0" });
    // the allowance is read once, of the token sent, to LI.FI's contract, with the signature the chain reader parses
    expect(chain.asked.filter((a) => a.startsWith("uint:"))).toEqual([`uint:Arbitrum:${USDC_ARB}:${ALLOWANCE}:${DEAD},${LIFI_DIAMOND}`]);
  });

  it("the same bridge from both orders is one route, and says so", async () => {
    const routes = ok(await routesFor(both({ body: Q_FASTEST }, { body: Q_FASTEST })));
    expect(routes).toHaveLength(1);
    expect(routes[0]!.native.orders).toEqual(["CHEAPEST", "FASTEST"]);
  });

  it("one order failing (LI.FI unreachable for it) still leaves the other's route", async () => {
    const routes = ok(await routesFor(both(new Error("socket hang up"), { body: Q_FASTEST })));
    expect(routes.map((r) => r.tool)).toEqual(["Across"]);
  });
});

describe("bridge routes: the approval", () => {
  const approvals = (r: BridgeRoute) => r.approval?.txs.map((t) => decodeFunctionData({ abi: erc20Abi, data: t.data }).args);

  it("short allowance: approve LI.FI's contract exactly the amount sent, on the token sent, before the transfer", async () => {
    const [r] = ok(await routesFor(both({ body: Q_FASTEST }, NO_ROUTE), { chain: chainStandIn({ ...RICH, allowance: 99_999_999n }) }));
    expect(r!.approval).toMatchObject({ token: USDC_ARB, spender: LIFI_DIAMOND, amount: "100000000" });
    expect(r!.approval!.txs[0]).toMatchObject({ chainId: 42161, chainIdHex: "0xa4b1", from: DEAD, to: USDC_ARB, value: "0x0" });
    expect(approvals(r!)).toEqual([[LIFI_DIAMOND, 100_000_000n]]);
  });

  it("enough allowance: no approval; unread allowance or no chain reader: the approval goes first anyway", async () => {
    expect(ok(await routesFor(both({ body: Q_FASTEST }, NO_ROUTE), { chain: chainStandIn({ ...RICH, allowance: 100_000_000n }) }))[0]!.approval).toBeUndefined();
    expect(approvals(ok(await routesFor(both({ body: Q_FASTEST }, NO_ROUTE), { chain: chainStandIn({ ...RICH, allowance: undefined }) }))[0]!)).toEqual([[LIFI_DIAMOND, 100_000_000n]]);
    const bare = ok(await routesFor(both({ body: Q_FASTEST }, NO_ROUTE), { chain: undefined }))[0]!;
    expect(approvals(bare)).toEqual([[LIFI_DIAMOND, 100_000_000n]]);
    expect(bare.native.allowance).toBe("unread");
  });

  it("a token that takes a new allowance only from zero (LI.FI's `approvalReset`): approve 0 first", async () => {
    const q = structuredClone(Q_FASTEST);
    q.estimate.approvalReset = true;
    const [r] = ok(await routesFor(both({ body: q }, NO_ROUTE), { chain: chainStandIn({ ...RICH, allowance: 5n }) }));
    expect(approvals(r!)).toEqual([[LIFI_DIAMOND, 0n], [LIFI_DIAMOND, 100_000_000n]]);
  });
});

describe("bridge routes: the destination is pinned", () => {
  it("LI.FI answering a transfer to another address is refused, whatever its summary says", async () => {
    const r = refusal(await routesFor(both({ body: Q_TOADDR }, { body: Q_TOADDR })));
    expect(r.code).toBe("E_VENUE_REJECTED");
    expect(r.message).toContain(BEEF);
    expect(r.message).toContain("Nothing was prepared");
  });

  it("a destination of the user's other than the wallet is paid exactly — the refund still goes to the sender (a real LI.FI answer)", async () => {
    const [r] = ok(await routesFor(both({ body: Q_TOADDR }, NO_ROUTE), { to: BEEF }));
    expect(r!.tool).toBe("Across");
    const call = decodeBridgeCall(r!.tx.data)!;
    expect(call.bridgeData.receiver).toBe(BEEF);
    expect(call.facetData.receiverAddress).toBe(pad(BEEF.toLowerCase() as Hex, { size: 32 }));
    expect(call.facetData.refundAddress).toBe(pad(DEAD.toLowerCase() as Hex, { size: 32 }));
  });

  it("one order paying another address is passed over, and the other order's route is kept, with the reason beside it", async () => {
    const routes = ok(await routesFor(both({ body: Q_CHEAPEST }, { body: Q_TOADDR })));
    expect(routes.map((r) => r.tool)).toEqual(["CCTP"]);
    expect(JSON.stringify(routes[0]!.native.passedOver)).toContain(BEEF);
  });

  it("the bridge's own recipient is read too: Across paying another address while LI.FI's record names the wallet is refused", async () => {
    const forged = recode(Q_FASTEST, (a) => (a[2].receiverAddress = pad(OTHER.toLowerCase() as Hex, { size: 32 })));
    expect(refusal(await routesFor(both({ body: forged }, NO_ROUTE))).message).toContain("Across would pay");
    const record = recode(Q_FASTEST, (a) => (a[0].receiver = OTHER));
    expect(refusal(await routesFor(both({ body: record }, NO_ROUTE))).message).toContain(`record the transfer as paying ${OTHER}`);
    const refund = recode(Q_FASTEST, (a) => (a[2].refundAddress = pad(OTHER.toLowerCase() as Hex, { size: 32 })));
    expect(refusal(await routesFor(both({ body: refund }, NO_ROUTE))).message).toContain("refund another address");
  });
});

describe("bridge routes: at least 97% arrives", () => {
  it("$96.99 at worst for $100 is refused; $97.00 is handed on", async () => {
    const low = refusal(await routesFor(both({ body: acrossPaying(96_990_000n) }, NO_ROUTE)));
    expect(low.code).toBe("E_ACCOUNT_REQUOTE");
    expect(low.message).toContain("$96.99");
    expect(ok(await routesFor(both({ body: acrossPaying(97_000_000n) }, NO_ROUTE)))[0]!.receiveUsd).toBe(97);
  });

  it("the least is the bridge's contract's, not LI.FI's summary: Across bound to deliver less than LI.FI quotes is refused", async () => {
    const q = recode(Q_FASTEST, (a) => (a[2].outputAmount = 90_000_000n));
    expect(refusal(await routesFor(both({ body: q }, NO_ROUTE))).message).toContain("not the least LI.FI quoted");
  });

  it("Across's contract recomputes what the relayer owes from the multiplier, not `outputAmount`: a short multiplier is refused", async () => {
    // LI.FI's real multiplier gives exactly its least: 99.75 × 0.999861904761904762 = 99.736225
    const call = decodeBridgeCall(Q_FASTEST.transactionRequest.data)!;
    expect((call.bridgeData.minAmount * (call.facetData.outputAmountMultiplier as bigint)) / 10n ** 18n).toBe(99_736_225n);
    // `outputAmount` and LI.FI's summary still say 99.736225; the relayer would owe 49.875
    const half = recode(Q_FASTEST, (a) => (a[2].outputAmountMultiplier = 5n * 10n ** 17n));
    const r = refusal(await routesFor(both({ body: half }, NO_ROUTE)));
    expect(r.code).toBe("E_VENUE_REJECTED");
    expect(r.message).toContain("multiplier is short");
    // and one asking more than any relayer fills (the money would sit until the deadline, then come back) is refused too
    const greedy = recode(Q_FASTEST, (a) => (a[2].outputAmountMultiplier = 2n * 10n ** 18n));
    expect(refusal(await routesFor(both({ body: greedy }, NO_ROUTE))).message).toContain("multiplier is off");
  });

  it("a multiplier one rounding unit short is taken, and the least shown is the contract's (99.736224), not LI.FI's", async () => {
    const q = recode(Q_FASTEST, (a) => (a[2].outputAmountMultiplier -= 5_100_000_000n));
    const [r] = ok(await routesFor(both({ body: q }, NO_ROUTE)));
    expect(r!.receiveUsd).toBe(99.736224);
    expect(r!.native.arrive).toMatchObject({ least: "99.736225", leastOnChain: "99.736224" });
  });

  it("CCTP fast: its fee is a cap, so the least minted sits under LI.FI's figure, and that is what is shown", async () => {
    const q = recode(Q_CHEAPEST, (a) => {
      a[0].bridge = "polymer";
      a[2].polymerTokenFee = 99_750n;
      a[2].maxCCTPFee = 141_050n;
      a[2].minFinalityThreshold = 1000;
    });
    q.tool = q.estimate.tool = "polymer";
    q.estimate.toAmount = q.estimate.toAmountMin = "99510600";
    q.estimate.executionDuration = 10;
    const [r] = ok(await routesFor(both({ body: q }, NO_ROUTE)));
    expect(r).toMatchObject({ tool: "CCTP fast", receiveUsd: 99.5092, etaSec: 10 });
    expect(r!.native.arrive).toMatchObject({ least: "99.5106", leastOnChain: "99.5092" });
  });
});

describe("bridge routes: the coin a transfer carries", () => {
  it("Stargate's LayerZero fee is paid on top in ETH: the transaction carries exactly it, and it is counted in the fee (a real LI.FI answer)", async () => {
    const [r] = ok(await routesFor(both({ body: Q_STARGATE }, NO_ROUTE)));
    expect(r).toMatchObject({ tool: "Stargate", receiveUsd: 99.191401, feeUsd: 0.57295, gasUsd: 0.0285, etaSec: 20 });
    expect(r!.tx.value).toBe("0x582aca04976e");
    expect(r!.native.paidOnTop).toEqual({ coin: "ETH", wei: "96940801169262", usd: 0.2628 });
  });

  it("a Stargate transfer carrying no coin, or paying LayerZero other than the fee it states, is refused", async () => {
    const none = structuredClone(Q_STARGATE);
    none.transactionRequest.value = "0x0";
    expect(refusal(await routesFor(both({ body: none }, NO_ROUTE))).message).toContain("not the fees it states are paid on top");
    const off = structuredClone(Q_STARGATE);
    off.estimate.feeCosts[1].amount = "1";
    off.transactionRequest.value = "0x1";
    expect(refusal(await routesFor(both({ body: off }, NO_ROUTE))).message).toContain("the fee it pays LayerZero is not the fee it states");
  });

  it("a Stargate transfer with LayerZero options (a native drop to another address is one) is refused", async () => {
    // LayerZero executor option: type 3 options, worker 1, length 49, native drop (type 2) of 0.01 ETH to another address
    const drop = `0x0003010031020000000000000000002386f26fc10000${pad(OTHER.toLowerCase() as Hex, { size: 32 }).slice(2)}` as Hex;
    const q = recode(Q_STARGATE, (a) => (a[2].sendParams.extraOptions = drop));
    expect(refusal(await routesFor(both({ body: q }, NO_ROUTE))).message).toContain("extra options");
  });

  it("an Across transfer carrying coin it states no fee for is refused", async () => {
    const q = structuredClone(Q_FASTEST);
    q.transactionRequest.value = "0x1";
    expect(refusal(await routesFor(both({ body: q }, NO_ROUTE))).code).toBe("E_VENUE_REJECTED");
  });

  it("a wallet with ETH for the gas but not for the gas and the LayerZero fee is not offered the Stargate route", async () => {
    const r = refusal(await routesFor(both({ body: Q_STARGATE }, NO_ROUTE), { chain: chainStandIn({ ...RICH, coin: { Arbitrum: 0.00005 } }) }));
    expect(r.code).toBe("E_VENUE_INSUFFICIENT");
    expect(r.message).toContain("fee paid on top");
  });
});

describe("bridge routes: what is never handed to a wallet", () => {
  const refused = async (q: Json, o: Partial<BridgeRouteRequest> = {}) => refusal(await routesFor(both({ body: q }, NO_ROUTE), o));

  it("a bridge whose own contract does not pay the address named (Relay, LayerSwap…): refused, even if LI.FI answers one", async () => {
    const q = structuredClone(Q_FASTEST);
    q.tool = q.estimate.tool = "relaydepository";
    expect((await refused(q)).message).toContain("relaydepository");
  });

  it("a hand-off to a contract on the arriving chain, another contract, another spender, another integrator, a fee bigger than stated", async () => {
    expect((await refused(recode(Q_FASTEST, (a) => (a[0].hasDestinationCall = true)))).message).toContain("instead of paying the address itself");
    const to = structuredClone(Q_FASTEST);
    to.transactionRequest.to = PERMIT2_PROXY;
    expect((await refused(to)).message).toContain("not addressed to LI.FI's own contract");
    const spender = structuredClone(Q_FASTEST);
    spender.estimate.approvalAddress = OTHER;
    expect((await refused(spender)).message).toContain("approve a spender");
    expect((await refused(recode(Q_FASTEST, (a) => (a[0].integrator = "jumper.exchange")))).message).toContain("integrator");
    const fee = recode(Q_FASTEST, (a) => (a[1][0].callData = encodeFunctionData({ abi: [{ type: "function", name: "forwardERC20Fees", stateMutability: "nonpayable", inputs: [{ name: "token", type: "address" }, { name: "distributions", type: "tuple[]", components: [{ name: "recipient", type: "address" }, { name: "amount", type: "uint256" }] }], outputs: [] }], functionName: "forwardERC20Fees", args: [USDC_ARB, [{ recipient: OTHER, amount: 300_000n }]] })));
    expect((await refused(fee)).message).toContain("the fee its call pays is not the fee LI.FI states");
    const pulls = recode(Q_FASTEST, (a) => a[1].push({ ...a[1][0], requiresDeposit: true }));
    expect((await refused(pulls)).code).toBe("E_VENUE_REJECTED");
  });

  it("an Across route minutes from its deadline is stale: ask again", async () => {
    const deadline = decodeBridgeCall(Q_FASTEST.transactionRequest.data)!.facetData.fillDeadline as number;
    expect((await refused(Q_FASTEST, { now: () => (deadline - 60) * 1000 })).message).toContain("ask again");
  });

  it("CCTP only for Circle's USDC to Circle's USDC: a Polymer route out of USDT0 is refused", async () => {
    const q = recode(Q_CHEAPEST, (a) => {
      a[0].sendingAssetId = USDT0_ARB;
      a[1][0].sendingAssetId = a[1][0].receivingAssetId = USDT0_ARB;
      a[1][0].callData = encodeFunctionData({ abi: [{ type: "function", name: "forwardERC20Fees", stateMutability: "nonpayable", inputs: [{ name: "token", type: "address" }, { name: "distributions", type: "tuple[]", components: [{ name: "recipient", type: "address" }, { name: "amount", type: "uint256" }] }], outputs: [] }], functionName: "forwardERC20Fees", args: [USDT0_ARB, [{ recipient: getAddress("0xC06ebbefD94032B85424D51906e2A335EFAe264B"), amount: 250_000n }]] });
    });
    q.action.fromToken.address = q.estimate.feeCosts[0].token.address = USDT0_ARB;
    expect((await refused(q, { asset: "USDT0" })).message).toContain("CCTP moves Circle's USDC");
  });
});

describe("bridge routes: LI.FI saying no", () => {
  it("no route: LI.FI's own reasons, as an order this venue does not take", async () => {
    const r = refusal(await routesFor(both(NO_ROUTE, NO_ROUTE)));
    expect(r.code).toBe("E_VENUE_ORDER_INVALID");
    expect(r.message).toContain("requires a signature on the destination chain");
  });

  it("rate-limited (75 quotes in two hours without a key): unreachable, try later", async () => {
    const r = refusal(await routesFor(both({ status: 429, body: { message: "Too many requests", code: 1005 } }, { status: 429, body: { message: "Too many requests", code: 1005 } })));
    expect(r.code).toBe("E_VENUE_UNREACHABLE");
    expect(r.message).toContain("75 quotes");
  });

  it("a bad address LI.FI itself rejects (HTTP 400 · 1011): its words", async () => {
    const bad = { status: 400, body: { message: "/toAddress Zero address is provided", code: 1011 } };
    expect(refusal(await routesFor(both(bad, bad))).message).toContain("/toAddress Zero address is provided");
  });
});

// ---- what became of it -------------------------------------------------------------------------------------------------------------

describe("bridge status: LI.FI's word, mapped", () => {
  const ST_HASH = ST_DONE.sending.txHash as Hex;
  const statusOf = (answer: Answer, o: Partial<Parameters<typeof bridgeStatus>[0]> = {}) => bridgeStatus({ http: lifi([[/\/v1\/status\?/, answer]]), hash: ST_HASH, fromChain: "Arbitrum", toChain: "Base", ...o });

  it("asks by the sending hash, both chains and the bridge's key (from its key or the name shown)", async () => {
    for (const tool of ["Across", "across"]) {
      const http = lifi([[/\/v1\/status\?/, { body: ST_DONE }]]);
      await bridgeStatus({ http, hash: ST_HASH, fromChain: "Arbitrum", toChain: "Base", tool });
      expect(lifiCalls(http)).toEqual([`GET https://li.quest/v1/status?txHash=${ST_HASH}&fromChain=42161&toChain=8453&bridge=across`]);
    }
    const http = lifi([[/\/v1\/status\?/, { body: ST_DONE }]]);
    await bridgeStatus({ http, hash: ST_HASH, fromChain: "Arbitrum", toChain: "Base", tool: "something new" });
    expect(lifiCalls(http)).toEqual([`GET https://li.quest/v1/status?txHash=${ST_HASH}&fromChain=42161&toChain=8453`]);
  });

  it("DONE · COMPLETED: settled, with what arrived and the transaction that paid it", async () => {
    const s = ok(await statusOf({ body: ST_DONE }));
    expect(s).toMatchObject({ status: "settled", received: 24997.29626, receivingHash: ST_DONE.receiving.txHash });
    expect(s.note).toContain("24997.29626 USDC on Base");
  });

  it("DONE · PARTIAL: settled, in another token on the arriving chain — said so; dollars counted only when it is a dollar stablecoin", async () => {
    const weth = ok(await statusOf({ body: ST_PARTIAL }, { hash: ST_PARTIAL.sending.txHash, fromChain: "Polygon", toChain: "Base" }));
    expect(weth.status).toBe("settled");
    expect(weth.received).toBeUndefined();
    expect(weth.note).toContain("as 0.229296266310768644 WETH, not VIRTUAL");
    const usdt = ok(await statusOf({ body: ST_STARGATE_PARTIAL }, { hash: ST_STARGATE_PARTIAL.sending.txHash, fromChain: "BNB Chain", toChain: "Ethereum" }));
    expect(usdt).toMatchObject({ status: "settled", received: 2.99834 });
    expect(usdt.note).toContain("in another token");
  });

  it("DONE · REFUNDED: failed — the money goes back to the sending wallet, on the sending chain", async () => {
    const s = ok(await statusOf({ body: { ...ST_DONE, substatus: "REFUNDED", substatusMessage: "The tokens were refunded to the sender address." } }));
    expect(s.status).toBe("failed");
    expect(s.note).toContain("The tokens were refunded to the sender address.");
    expect(s.note).toContain("back to the sending wallet on Arbitrum, in USDC");
    // the refund recorded as received on the SENDING chain is this transfer coming back, not an answer about another one
    const back = { ...ST_DONE, substatus: "REFUNDED", receiving: { ...ST_DONE.receiving, chainId: 42161, token: ST_DONE.sending.token } };
    expect(ok(await statusOf({ body: back })).status).toBe("failed");
    // but "arrived" on the sending chain is not this transfer arriving: never settled
    expect(refusal(await statusOf({ body: { ...back, substatus: "COMPLETED" } })).message).toContain("other chains");
  });

  it("FAILED, every documented substatus: failed, in LI.FI's words; a refund LI.FI owes is said to come on the sending chain", async () => {
    for (const sub of ["NOT_PROCESSABLE_REFUND_NEEDED", "OUT_OF_GAS", "SLIPPAGE_EXCEEDED", "INSUFFICIENT_ALLOWANCE", "INSUFFICIENT_BALANCE", "EXPIRED", "UNKNOWN_ERROR", "REFUNDED"]) {
      const s = ok(await statusOf({ body: { ...ST_DONE, status: "FAILED", substatus: sub, substatusMessage: `said: ${sub}` } }));
      expect(s.status, sub).toBe("failed");
      expect(s.note).toContain(`said: ${sub}`);
      if (sub === "NOT_PROCESSABLE_REFUND_NEEDED") expect(s.note).toContain("refunds it on Arbitrum");
    }
  });

  it("PENDING, every substatus (three real ones: CCTP waiting for finality, Celer down, Relay stuck for days): pending, in LI.FI's words", async () => {
    const real: Array<[Json, ChainName, ChainName]> = [[ST_POLYMER_PENDING, "Base", "Ethereum"], [ST_CELER_NA, "Ethereum", "Polygon"], [ST_RELAY_STUCK, "Ethereum", "Polygon"]];
    for (const [body, fromChain, toChain] of real) {
      const s = ok(await statusOf({ body }, { hash: body.sending.txHash, fromChain, toChain }));
      expect(s.status).toBe("pending");
      expect(s.note).toContain(body.substatusMessage);
      expect(s.received).toBeUndefined();
    }
    for (const sub of ["WAIT_SOURCE_CONFIRMATIONS", "WAIT_DESTINATION_TRANSACTION", "BRIDGE_NOT_AVAILABLE", "CHAIN_NOT_AVAILABLE", "REFUND_IN_PROGRESS", "UNKNOWN_ERROR"]) {
      expect(ok(await statusOf({ body: { ...ST_RELAY_STUCK, status: "PENDING", substatus: sub } }, { hash: ST_RELAY_STUCK.sending.txHash, fromChain: "Ethereum", toChain: "Polygon" })).status, sub).toBe("pending");
    }
  });

  it("not seen yet (404 · 1003, or NOT_FOUND): pending — unless the sending chain shows it reverted", async () => {
    for (const answer of [{ status: 404, body: ST_NOTFOUND }, { body: { status: "NOT_FOUND" } }] as Answer[]) {
      expect(ok(await statusOf(answer)).status).toBe("pending");
      const reverted: Mined = { status: "reverted", from: DEAD, to: LIFI_DIAMOND, logs: [] };
      const mined: Mined = { ...reverted, status: "success" };
      expect(ok(await statusOf(answer, { chain: chainStandIn({ receipts: { [ST_HASH.toLowerCase()]: reverted } }) }))).toMatchObject({ status: "failed" });
      expect(ok(await statusOf(answer, { chain: chainStandIn({ receipts: { [ST_HASH.toLowerCase()]: mined } }) })).status).toBe("pending");
      expect(ok(await statusOf(answer, { chain: chainStandIn() })).status).toBe("pending");
      // a reverted transaction to another contract is not this transfer's end
      expect(ok(await statusOf(answer, { chain: chainStandIn({ receipts: { [ST_HASH.toLowerCase()]: { ...reverted, to: OTHER } } }) })).status).toBe("pending");
    }
  });

  it("anything not read as arrived or as lost stays pending: DONE with a new word, INVALID, LI.FI unreachable, rate-limited, broken", async () => {
    for (const answer of [{ body: { ...ST_DONE, substatus: "SOMETHING_NEW" } }, { body: { ...ST_DONE, substatus: undefined } }, { body: { status: "INVALID" } }, new Error("timeout"), { status: 429, body: { code: 1005 } }, { status: 500, text: "oops" }] as Answer[]) {
      expect(ok(await statusOf(answer)).status).toBe("pending");
    }
  });

  it("an answer about another transfer is refused: another sender, another receiver, other chains, other transactions", async () => {
    expect(refusal(await statusOf({ body: ST_DONE }, { from: OTHER })).message).toContain("another transfer");
    expect(refusal(await statusOf({ body: ST_DONE }, { to: OTHER })).code).toBe("E_VENUE_REJECTED");
    expect(refusal(await statusOf({ body: ST_DONE }, { fromChain: "Optimism" })).message).toContain("other chains");
    expect(refusal(await statusOf({ body: ST_DONE }, { hash: HASH })).message).toContain("other transactions");
    // asked by the receiving hash, it is the same transfer
    expect(ok(await statusOf({ body: ST_DONE }, { hash: ST_DONE.receiving.txHash })).status).toBe("settled");
    expect(ok(await statusOf({ body: ST_DONE }, { from: ST_DONE.fromAddress, to: ST_DONE.toAddress })).status).toBe("settled");
  });

  it("a question that cannot be asked is refused without asking", async () => {
    const http = lifi([]);
    expect(refusal(await bridgeStatus({ http, hash: "0x1234" as Hex, fromChain: "Arbitrum", toChain: "Base" })).code).toBe("E_ACCOUNT_BAD_ACTION");
    expect(refusal(await bridgeStatus({ http, hash: ST_HASH, fromChain: "Base", toChain: "Base" })).code).toBe("E_ACCOUNT_BAD_ACTION");
    expect(http.asked).toEqual([]);
  });
});

