describe("confirm sent: the hash is the transaction that was built", () => {
  /** a real transfer straight to LI.FI's contract on Arbitrum (2.89 USDT0 → USDC on Base, by Across), as it was built */
  const BUILT: BridgeTx = { chainId: 42161, chainIdHex: "0xa4b1", from: getAddress(TX_USDT0.from), to: LIFI_DIAMOND, data: TX_USDT0.input, value: "0x0", gas: TX_USDT0.gas };
  const SEEN: SentTx = { from: TX_USDT0.from, to: TX_USDT0.to, data: TX_USDT0.input, value: 0n, chainId: 42161 };
  const key = TX_USDT0.hash.toLowerCase();

  it("the same sender, contract, call, coin and chain: ok — through a chain reader, or an RPC's own answer (`input`, hex value and chain id)", async () => {
    expect(await confirmSent({ chain: chainStandIn({ txs: { [key]: SEEN } }), expected: BUILT, hash: TX_USDT0.hash })).toBe("ok");
    const getTx = async () => ({ from: TX_USDT0.from, to: TX_USDT0.to, input: TX_USDT0.input, value: TX_USDT0.value, chainId: TX_USDT0.chainId });
    expect(await confirmSent({ getTx, expected: BUILT, hash: TX_USDT0.hash })).toBe("ok");
  });

  it("anything else is refused, each difference named: Jumper's gasless proxy, another call, coin, sender or chain", async () => {
    const flip = (TX_USDT0.input as string).slice(0, -2) + ((TX_USDT0.input as string).endsWith("00") ? "01" : "00");
    const cases: Array<[Partial<SentTx>, string]> = [
      [{ to: PERMIT2_PROXY }, `it goes to ${PERMIT2_PROXY}`],
      [{ data: flip as Hex }, "its call is not the one built"],
      [{ value: 1n }, "it carries 1 wei of ETH"],
      [{ from: OTHER }, `it is from ${OTHER}`],
      [{ chainId: 8453 }, "it is for chain 8453"],
    ];
    for (const [change, words] of cases) {
      const r = refusal(await confirmSent({ chain: chainStandIn({ txs: { [key]: { ...SEEN, ...change } } }), expected: BUILT, hash: TX_USDT0.hash }));
      expect(r.code).toBe("E_VENUE_REJECTED");
      expect(r.message).toContain(words);
    }
  });

  it("not seen yet: pending — and a reader that can read transactions is never downgraded to the receipt when it does not see one", async () => {
    expect(await confirmSent({ chain: chainStandIn(), expected: BUILT, hash: TX_USDT0.hash })).toBe("pending");
    const RC: Mined = { status: "success", from: getAddress(RC_USDT0.from), to: getAddress(RC_USDT0.to), logs: RC_USDT0.logs };
    const lagging = chainStandIn({ receipts: { [key]: RC } });
    expect(await confirmSent({ chain: lagging, expected: BUILT, hash: TX_USDT0.hash })).toBe("pending");
    expect(lagging.asked.some((a) => a.startsWith("receipt:"))).toBe(false);
    expect(await confirmSent({ chain: lagging, getTx: async () => { throw new Error("rpc down"); }, expected: BUILT, hash: TX_USDT0.hash })).toBe("pending");
  });

  it("a reader with receipts only: LI.FI's own log of the transfer starting, with this transfer's id and receiver, in the real receipt", async () => {
    const receiptsOnly = (receipts: Record<string, Mined>) => {
      const { transaction: _none, ...rest } = chainStandIn({ receipts });
      return rest;
    };
    const RC: Mined = { status: "success", from: getAddress(RC_USDT0.from), to: getAddress(RC_USDT0.to), logs: RC_USDT0.logs };
    expect(await confirmSent({ chain: receiptsOnly({ [key]: RC }), expected: BUILT, hash: TX_USDT0.hash })).toBe("ok");
    expect(await confirmSent({ chain: receiptsOnly({}), expected: BUILT, hash: TX_USDT0.hash })).toBe("pending");
    expect(refusal(await confirmSent({ chain: receiptsOnly({ [key]: { ...RC, from: OTHER } }), expected: BUILT, hash: TX_USDT0.hash })).message).toContain(`it is from ${OTHER}`);
    expect(refusal(await confirmSent({ chain: receiptsOnly({ [key]: { ...RC, status: "reverted", logs: [] } }), expected: BUILT, hash: TX_USDT0.hash })).message).toContain("reverted");
    // the same receipt held to another transfer (another id in the built call) is not it
    const another = recode({ transactionRequest: { data: BUILT.data } }, (a) => (a[0].transactionId = `0x${"ab".repeat(32)}`)).transactionRequest.data;
    expect(refusal(await confirmSent({ chain: receiptsOnly({ [key]: RC }), expected: { ...BUILT, data: another }, hash: TX_USDT0.hash })).message).toContain("logged no transfer");
    // the same id in a record that differs anywhere else (a hand-off on arrival, another bridge, another integrator) is not it either
    for (const change of [(a: Json[]) => (a[0].hasDestinationCall = true), (a: Json[]) => (a[0].bridge = "relaydepository"), (a: Json[]) => (a[0].integrator = "account-demo")]) {
      const built = recode({ transactionRequest: { data: BUILT.data } }, change).transactionRequest.data;
      expect(refusal(await confirmSent({ chain: receiptsOnly({ [key]: RC }), expected: { ...BUILT, data: built }, hash: TX_USDT0.hash })).message).toContain("logged no transfer");
    }
  });

  it("a malformed hash, a chain not bridged from, or no way to read the chain: refused", async () => {
    expect(refusal(await confirmSent({ chain: chainStandIn(), expected: BUILT, hash: "0xabc" as Hex })).code).toBe("E_ACCOUNT_BAD_ACTION");
    expect(refusal(await confirmSent({ chain: chainStandIn(), expected: { ...BUILT, chainId: 4663 }, hash: TX_USDT0.hash })).code).toBe("E_ACCOUNT_BAD_ACTION");
    expect(refusal(await confirmSent({ expected: BUILT, hash: TX_USDT0.hash })).code).toBe("E_ACCOUNT_BAD_ACTION");
  });
});
